CREATE TABLE IF NOT EXISTS "personal_access_tokens" ("id" integer not null primary key autoincrement, "tokenable_type" varchar not null, "tokenable_id" integer not null, "name" varchar not null, "token" varchar not null, "abilities" text, "last_used_at" datetime, "created_at" datetime, "updated_at" datetime);
CREATE TABLE IF NOT EXISTS "projects" ("id" integer not null primary key autoincrement, "author_id" integer, "project_category" integer, "project_title" varchar not null, "slug" varchar not null, "project_type" varchar check ("project_type" in ('hourly', 'fixed')), "project_payout_type" varchar check ("project_payout_type" in ('fixed', 'both', 'milestone', 'hourly')), "attachments" text, "project_description" text, "project_payment_mode" varchar, "project_max_hours" varchar, "project_min_price" float not null default '0', "project_max_price" float not null default '0', "project_country" varchar, "country_zipcode" varchar, "address" text, "project_duration" integer, "project_hiring_seller" integer, "project_expert_level" integer, "project_location" integer, "is_featured" integer not null default '0', "featured_expiry" datetime, "status" varchar check ("status" in ('draft', 'pending', 'publish', 'hired', 'completed', 'refunded', 'cancelled')) not null default 'draft', "deleted_at" datetime, "created_at" datetime, "updated_at" datetime);
CREATE TABLE IF NOT EXISTS "gig_orders" ("id" integer not null primary key autoincrement, "author_id" integer, "gig_id" integer, "plan_type" varchar not null, "plan_amount" float not null default '0', "gig_features" text, "gig_addons" text, "downloadable" text, "gig_delivery_days" integer not null, "gig_start_time" datetime, "commission_type" integer not null default '0', "commission_amount" float not null default '0', "status" varchar check ("status" in ('draft', 'hired', 'queued', 'completed', 'disputed', 'refunded', 'rejected')) not null default 'draft', "deleted_at" datetime, "created_at" datetime, "updated_at" datetime);
CREATE TABLE IF NOT EXISTS "project_durations" ("id" integer not null primary key autoincrement, "name" varchar not null, "status" varchar check ("status" in ('active', 'deactive')) not null default 'active', "deleted_at" datetime, "created_at" datetime, "updated_at" datetime);
CREATE TABLE IF NOT EXISTS "seller_project_invites" ("id" integer not null primary key autoincrement, "seller_id" integer not null, "project_id" integer not null, "created_at" datetime, "updated_at" datetime);
CREATE TABLE IF NOT EXISTS "project_locations" ("id" integer not null primary key autoincrement, "name" varchar not null, "status" varchar check ("status" in ('active', 'deactive')) not null default 'active', "deleted_at" datetime, "created_at" datetime, "updated_at" datetime);
CREATE TABLE IF NOT EXISTS "escrow_disburse_methods" ("id" integer not null primary key autoincrement, "seller_id" integer not null, "project_id" integer not null, "disburse_methods_id" integer not null, "created_at" datetime, "updated_at" datetime);
CREATE TABLE IF NOT EXISTS "gig_order_activities" ("id" integer not null primary key autoincrement, "sender_id" integer not null, "receiver_id" integer not null, "gig_id" integer not null, "order_id" integer not null, "type" varchar check ("type" in ('revision', 'final')) not null default 'revision', "attachments" text, "description" text not null, "created_at" datetime, "updated_at" datetime);
CREATE TABLE IF NOT EXISTS "project_activities" ("id" integer not null primary key autoincrement, "sender_id" integer not null, "receiver_id" integer not null, "project_id" integer not null, "attachments" text, "description" text not null, "created_at" datetime, "updated_at" datetime);
CREATE TABLE IF NOT EXISTS "disputes" ("id" integer not null primary key autoincrement, "created_by" integer, "created_to" integer, "proposal_id" integer, "gig_order_id" integer, "price" float not null default '0', "dispute_issue" varchar, "dispute_detail" text, "dispute_log" text, "resolved_by" varchar check ("resolved_by" in ('admin', 'seller')) not null default 'seller', "favour_to" varchar check ("favour_to" in ('seller', 'buyer')), "status" varchar check ("status" in ('publish', 'declined', 'refunded', 'resolved', 'disputed', 'processing', 'cancelled')) not null default 'publish', "created_at" datetime, "updated_at" datetime);
CREATE TABLE IF NOT EXISTS "dispute_conversations" ("id" integer not null primary key autoincrement, "sender_id" integer not null, "dispute_id" integer not null, "message_id" integer, "message" text, "attachments" text, "created_at" datetime, "updated_at" datetime);
CREATE TABLE IF NOT EXISTS "project_categories" ("id" integer not null primary key autoincrement, "parent_id" integer, "name" varchar not null, "image" text, "slug" varchar not null, "description" text, "status" varchar check ("status" in ('active', 'deactive')) not null default 'active', "deleted_at" datetime, "created_at" datetime, "updated_at" datetime);
CREATE TABLE IF NOT EXISTS "gig_categories" ("id" integer not null primary key autoincrement, "parent_id" integer, "name" varchar not null, "image" text, "slug" varchar not null, "description" text, "status" varchar check ("status" in ('active', 'deactive')) not null default 'active', "deleted_at" datetime, "created_at" datetime, "updated_at" datetime);
CREATE TABLE IF NOT EXISTS "gig_category_features" ("id" integer not null primary key autoincrement, "category_id" integer, "label" varchar not null, "options" text, "created_at" datetime, "updated_at" datetime);
CREATE TABLE IF NOT EXISTS "gigs" ("id" integer not null primary key autoincrement, "author_id" integer not null, "title" varchar not null, "slug" varchar not null, "country" varchar not null, "zipcode" varchar not null, "address" text, "description" text, "attachments" text, "downloadable" text, "is_featured" integer not null default '0', "featured_expiry" datetime, "status" varchar check ("status" in ('publish', 'draft')) not null default 'publish', "deleted_at" datetime, "created_at" datetime, "updated_at" datetime);
CREATE TABLE IF NOT EXISTS "gig_plans" ("id" integer not null primary key autoincrement, "gig_id" integer, "title" varchar not null, "description" text, "price" float not null default '0', "delivery_time" integer not null, "is_featured" integer not null default '0', "options" text, "created_at" datetime, "updated_at" datetime);
CREATE TABLE IF NOT EXISTS "gig_addons" ("id" integer not null primary key autoincrement, "gig_id" integer not null, "addon_id" integer not null, "created_at" datetime, "updated_at" datetime);
CREATE TABLE IF NOT EXISTS "gig_faqs" ("id" integer not null primary key autoincrement, "gig_id" integer not null, "question" text not null, "answer" text not null, "created_at" datetime, "updated_at" datetime);
CREATE TABLE IF NOT EXISTS "gig_tags" ("id" integer not null primary key autoincrement, "gig_id" integer not null, "tag_name" varchar not null, "created_at" datetime, "updated_at" datetime);
CREATE TABLE IF NOT EXISTS "gig_category_link" ("id" integer not null primary key autoincrement, "gig_id" integer not null, "category_id" integer not null, "category_level" integer not null, "created_at" datetime, "updated_at" datetime, foreign key("gig_id") references "gigs"("id"), foreign key("category_id") references "gig_categories"("id"));
CREATE TABLE IF NOT EXISTS "advertisers" ("id" integer not null primary key autoincrement, "user_id" integer not null, "name" varchar not null, "billing_email" varchar not null, "daily_spend_limit" numeric, "lifetime_spend_limit" numeric, "wallet_balance" numeric not null default '0', "status" varchar not null default 'active', "affiliate_id" integer, "created_at" datetime, "updated_at" datetime, foreign key("user_id") references "users"("id") on delete cascade, foreign key("affiliate_id") references "users"("id") on delete set null);
CREATE TABLE IF NOT EXISTS "project_freelancers" ("id" integer not null primary key autoincrement, "project_id" integer not null, "freelancer" varchar not null, "role" varchar not null default 'contributor', "created_at" datetime, "updated_at" datetime);
CREATE TABLE IF NOT EXISTS "project_tasks" ("id" integer not null primary key autoincrement, "project_id" integer not null, "title" varchar not null, "assignee" varchar, "status" varchar not null default 'pending', "due_date" datetime, "hours_logged" numeric not null default '0', "created_at" datetime, "updated_at" datetime);
CREATE TABLE IF NOT EXISTS "project_milestones" ("id" integer not null primary key autoincrement, "project_id" integer not null, "title" varchar not null, "amount" numeric not null, "status" varchar not null default 'pending', "due_date" datetime, "created_at" datetime, "updated_at" datetime);
CREATE TABLE IF NOT EXISTS "project_submissions" ("id" integer not null primary key autoincrement, "project_id" integer not null, "milestone_id" integer, "notes" text not null, "attachment_url" varchar, "status" varchar not null default 'submitted', "created_at" datetime, "updated_at" datetime);
CREATE TABLE IF NOT EXISTS "project_invitations" ("id" integer not null primary key autoincrement, "project_id" integer not null, "freelancer" varchar not null, "message" text, "status" varchar not null default 'pending', "created_at" datetime, "updated_at" datetime);
CREATE TABLE IF NOT EXISTS "project_time_logs" ("id" integer not null primary key autoincrement, "project_id" integer not null, "freelancer" varchar not null, "hours" numeric not null, "note" text, "logged_at" datetime not null, "created_at" datetime, "updated_at" datetime);
CREATE TABLE IF NOT EXISTS "project_reviews" ("id" integer not null primary key autoincrement, "project_id" integer not null, "rating" numeric not null, "comment" text, "author" varchar not null, "created_at" datetime, "updated_at" datetime);
CREATE TABLE IF NOT EXISTS "gig_timeline_items" ("id" integer not null primary key autoincrement, "gig_id" integer not null, "title" varchar not null, "description" text, "occurred_at" datetime not null, "created_at" datetime, "updated_at" datetime);
CREATE TABLE IF NOT EXISTS "gig_packages" ("id" integer not null primary key autoincrement, "gig_id" integer not null, "name" varchar not null, "price" numeric not null, "delivery_time" integer not null, "created_at" datetime, "updated_at" datetime);
CREATE TABLE IF NOT EXISTS "gig_requirements" ("id" integer not null primary key autoincrement, "gig_id" integer not null, "prompt" text not null, "created_at" datetime, "updated_at" datetime);
CREATE TABLE IF NOT EXISTS "gig_change_requests" ("id" integer not null primary key autoincrement, "gig_id" integer not null, "requester" varchar not null, "notes" text not null, "status" varchar not null default 'pending', "created_at" datetime, "updated_at" datetime);
CREATE TABLE IF NOT EXISTS "gig_reviews" ("id" integer not null primary key autoincrement, "gig_id" integer not null, "rating" numeric not null, "comment" text, "author" varchar not null, "created_at" datetime, "updated_at" datetime);
CREATE TABLE IF NOT EXISTS "profile_portfolios" ("id" integer not null primary key autoincrement, "user_id" integer not null, "title" varchar not null, "description" text, "link" varchar, "thumbnail_url" varchar, "featured" tinyint(1) not null default '0', "completed_at" datetime, "created_at" datetime, "updated_at" datetime);
CREATE TABLE IF NOT EXISTS "profile_reviews" ("id" integer not null primary key autoincrement, "user_id" integer not null, "reviewer" varchar, "rating" numeric not null, "comment" text, "reference" varchar, "created_at" datetime, "updated_at" datetime);
CREATE TABLE IF NOT EXISTS "profile_educations" ("id" integer not null primary key autoincrement, "user_id" integer not null, "institution" varchar not null, "degree" varchar, "field" varchar, "start_year" integer, "end_year" integer, "created_at" datetime, "updated_at" datetime);
CREATE TABLE IF NOT EXISTS "profile_certifications" ("id" integer not null primary key autoincrement, "user_id" integer not null, "name" varchar not null, "issuer" varchar, "credential_url" varchar, "issued_at" datetime, "expires_at" datetime, "created_at" datetime, "updated_at" datetime);
CREATE TABLE IF NOT EXISTS "custom_gigs" ("id" integer not null primary key autoincrement, "title" varchar not null, "buyer" varchar not null, "scope" text, "status" varchar not null default 'draft', "created_at" datetime, "updated_at" datetime);
