CREATE TABLE IF NOT EXISTS "launchpad_applications" ("id" integer not null primary key autoincrement, "launchpad_programme_id" integer not null, "user_id" integer not null, "status" varchar not null default 'submitted', "motivation" text, "reference_issued" tinyint(1) not null default '0', "qualification_issued" tinyint(1) not null default '0', "hours_gained" integer not null default '0', "weeks_gained" integer not null default '0', "created_at" datetime, "updated_at" datetime, foreign key("launchpad_programme_id") references "launchpad_programmes"("id"), foreign key("user_id") references "users"("id"));
CREATE TABLE IF NOT EXISTS "launchpad_interviews" ("id" integer not null primary key autoincrement, "launchpad_application_id" integer not null, "scheduled_by" integer not null, "scheduled_at" datetime not null, "status" varchar not null default 'scheduled', "notes" text, "created_at" datetime, "updated_at" datetime, foreign key("launchpad_application_id") references "launchpad_applications"("id"), foreign key("scheduled_by") references "users"("id"));
CREATE TABLE IF NOT EXISTS "tickets" ("id" integer not null primary key autoincrement, "ticketable_type" varchar not null, "ticketable_id" integer not null, "user_id" integer, "price" numeric not null default '0', "currency" varchar not null default 'USD', "status" varchar not null default 'available', "metadata" text, "created_at" datetime, "updated_at" datetime, foreign key("user_id") references "users"("id"));
CREATE TABLE IF NOT EXISTS "launchpad_application_task_progress" ("id" integer not null primary key autoincrement, "launchpad_application_id" integer not null, "launchpad_task_id" integer not null, "completed_at" datetime, "created_at" datetime, "updated_at" datetime, foreign key("launchpad_application_id") references "launchpad_applications"("id"), foreign key("launchpad_task_id") references "launchpad_tasks"("id"));
CREATE TABLE IF NOT EXISTS "networking_contact_exchanges" ("id" integer not null primary key autoincrement, "networking_session_id" integer not null, "user_id" integer not null, "partner_id" integer not null, "starred" tinyint(1) not null default '0', "follow_up_at" datetime, "notes" text, "metadata" text, "created_at" datetime, "updated_at" datetime, foreign key("networking_session_id") references "networking_sessions"("id"), foreign key("user_id") references "users"("id"), foreign key("partner_id") references "users"("id"));
CREATE TABLE IF NOT EXISTS "podcast_series_followers" ("id" integer not null primary key autoincrement, "podcast_series_id" integer not null, "user_id" integer not null, "created_at" datetime, "updated_at" datetime, foreign key("podcast_series_id") references "podcast_series"("id") on delete cascade, foreign key("user_id") references "users"("id") on delete cascade);
CREATE TABLE IF NOT EXISTS "podcast_episode_transcripts" ("id" integer not null primary key autoincrement, "podcast_episode_id" integer not null, "language" varchar not null default 'en', "source" varchar, "content" text not null, "metadata" text, "created_at" datetime, "updated_at" datetime, foreign key("podcast_episode_id") references "podcast_episodes"("id") on delete cascade);
CREATE TABLE IF NOT EXISTS "podcast_episode_highlights" ("id" integer not null primary key autoincrement, "podcast_episode_id" integer not null, "title" varchar not null, "description" text, "starts_at_seconds" integer not null, "ends_at_seconds" integer, "metadata" text, "created_at" datetime, "updated_at" datetime, foreign key("podcast_episode_id") references "podcast_episodes"("id") on delete cascade);
CREATE TABLE IF NOT EXISTS "podcast_episode_entitlements" ("id" integer not null primary key autoincrement, "podcast_episode_id" integer not null, "user_id" integer not null, "entitlement_type" varchar not null, "source" varchar, "granted_at" datetime default CURRENT_TIMESTAMP not null, "expires_at" datetime, "metadata" text, "created_at" datetime, "updated_at" datetime, foreign key("podcast_episode_id") references "podcast_episodes"("id") on delete cascade);
CREATE TABLE IF NOT EXISTS "networking_pairings" ("id" integer not null primary key autoincrement, "networking_session_id" integer not null, "participant_id" integer not null, "partner_id" integer, "round" integer not null, "group_key" varchar, "metadata" text, "created_at" datetime, "updated_at" datetime, foreign key("networking_session_id") references "networking_sessions"("id") on delete cascade);
CREATE TABLE IF NOT EXISTS "ad_groups" ("id" integer not null primary key autoincrement, "campaign_id" integer not null, "name" varchar not null, "daily_budget" numeric, "bid_amount" numeric, "status" varchar not null default 'active', "created_at" datetime, "updated_at" datetime, foreign key("campaign_id") references "campaigns"("id") on delete cascade);
CREATE TABLE IF NOT EXISTS "ai_sessions" ("id" integer not null primary key autoincrement, "user_id" integer not null, "tool" varchar not null, "status" varchar not null default 'pending', "prompt_tokens" integer not null default '0', "completion_tokens" integer not null default '0', "credit_cost" integer not null default '0', "input" text, "output" text, "created_at" datetime, "updated_at" datetime, foreign key("user_id") references "users"("id"));
CREATE TABLE IF NOT EXISTS "ai_byok_credentials" ("id" integer not null primary key autoincrement, "user_id" integer not null, "provider" varchar not null, "api_key" varchar not null, "meta" text, "created_at" datetime, "updated_at" datetime, foreign key("user_id") references "users"("id"));
CREATE TABLE IF NOT EXISTS "ai_subscription_plans" ("id" integer not null primary key autoincrement, "name" varchar not null, "slug" varchar not null, "limits" text, "price" numeric not null default '0', "created_at" datetime, "updated_at" datetime);
