CREATE TABLE IF NOT EXISTS "ai_usage_aggregates" ("id" integer not null primary key autoincrement, "user_id" integer not null, "period_start" date not null, "period_end" date not null, "tokens_used" integer not null default '0', "sessions_count" integer not null default '0', "created_at" datetime, "updated_at" datetime, foreign key("user_id") references "users"("id"));
CREATE TABLE IF NOT EXISTS "creatives" ("id" integer not null primary key autoincrement, "campaign_id" integer not null, "ad_group_id" integer, "type" varchar not null, "title" varchar not null, "body" text, "destination_url" varchar, "media_path" varchar, "status" varchar not null default 'draft', "cta" varchar, "created_at" datetime, "updated_at" datetime, foreign key("campaign_id") references "campaigns"("id") on delete cascade, foreign key("ad_group_id") references "ad_groups"("id") on delete set null);
CREATE TABLE IF NOT EXISTS "volunteering_opportunities" ("id" integer not null primary key autoincrement, "organisation_id" integer, "creator_id" integer not null, "title" varchar not null, "sector" varchar not null, "location" varchar, "commitment" varchar, "expenses_covered" tinyint(1) not null default '0', "verified" tinyint(1) not null default '0', "status" varchar not null default 'draft', "description" text, "created_at" datetime, "updated_at" datetime, foreign key("organisation_id") references "organizations"("id"), foreign key("creator_id") references "users"("id"));
CREATE TABLE IF NOT EXISTS "volunteering_applications" ("id" integer not null primary key autoincrement, "volunteering_opportunity_id" integer not null, "user_id" integer not null, "status" varchar not null default 'submitted', "motivation" text, "hours_contributed" integer not null default '0', "created_at" datetime, "updated_at" datetime, foreign key("volunteering_opportunity_id") references "volunteering_opportunities"("id"), foreign key("user_id") references "users"("id"));
